import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_triplet_margin_loss(torch::Tensor anchor, torch::Tensor positive, torch::Tensor negative, double margin, double eps);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void triplet_margin_loss_kernel(
    const float* __restrict__ A,
    const float* __restrict__ P,
    const float* __restrict__ N,
    float* __restrict__ loss_sum,
    int batch, int dim,
    float margin, float eps)
{
    int row = blockIdx.x;
    if (row >= batch) return;
    const float* a_row = A + (size_t)row * dim;
    const float* p_row = P + (size_t)row * dim;
    const float* n_row = N + (size_t)row * dim;
    float sum_pos = 0.f;
    float sum_neg = 0.f;
    // Vectorized loads (float4) for coalesced, higher-throughput global memory access.
    int dim4 = dim >> 2;
    const float4* a4 = reinterpret_cast<const float4*>(a_row);
    const float4* p4 = reinterpret_cast<const float4*>(p_row);
    const float4* n4 = reinterpret_cast<const float4*>(n_row);
    for (int i = threadIdx.x; i < dim4; i += blockDim.x) {
        float4 av = __ldg(&a4[i]);
        float4 pv = __ldg(&p4[i]);
        float4 nv = __ldg(&n4[i]);
        float dpx = av.x - pv.x + eps;
        float dpy = av.y - pv.y + eps;
        float dpz = av.z - pv.z + eps;
        float dpw = av.w - pv.w + eps;
        float dnx = av.x - nv.x + eps;
        float dny = av.y - nv.y + eps;
        float dnz = av.z - nv.z + eps;
        float dnw = av.w - nv.w + eps;
        sum_pos += dpx * dpx + dpy * dpy + dpz * dpz + dpw * dpw;
        sum_neg += dnx * dnx + dny * dny + dnz * dnz + dnw * dnw;
    }
    // Handle any tail elements when dim is not a multiple of 4.
    for (int i = dim4 * 4 + threadIdx.x; i < dim; i += blockDim.x) {
        float av = __ldg(&a_row[i]);
        float pv = __ldg(&p_row[i]);
        float nv = __ldg(&n_row[i]);
        float dp = av - pv + eps;
        float dn = av - nv + eps;
        sum_pos += dp * dp;
        sum_neg += dn * dn;
    }
    // Warp-level reduction: pack sum_pos and sum_neg into a single 64-bit
    // value so both reductions can be performed with one shuffle
    // instruction per step instead of two, halving shuffle overhead
    // and shared-memory footprint/bank-conflict pressure.
    double packed = __hiloint2double(__float_as_int(sum_neg), __float_as_int(sum_pos));
    for (int offset = 16; offset > 0; offset >>= 1) {
        double other = __shfl_down_sync(0xffffffff, packed, offset);
        float other_pos = __int_as_float(__double2loint(other));
        float other_neg = __int_as_float(__double2hiint(other));
        float p = __int_as_float(__double2loint(packed)) + other_pos;
        float n = __int_as_float(__double2hiint(packed)) + other_neg;
        packed = __hiloint2double(__float_as_int(n), __float_as_int(p));
    }
    __shared__ double shared_packed[32];
    int lane = threadIdx.x & 31;
    int wid  = threadIdx.x >> 5;
    if (lane == 0) {
        shared_packed[wid] = packed;
    }
    __syncthreads();
    int numWarps = (blockDim.x + 31) / 32;
    if (wid == 0) {
        packed = (lane < numWarps) ? shared_packed[lane] : __hiloint2double(0, 0);
        for (int offset = 16; offset > 0; offset >>= 1) {
            double other = __shfl_down_sync(0xffffffff, packed, offset);
            float other_pos = __int_as_float(__double2loint(other));
            float other_neg = __int_as_float(__double2hiint(other));
            float p = __int_as_float(__double2loint(packed)) + other_pos;
            float n = __int_as_float(__double2hiint(packed)) + other_neg;
            packed = __hiloint2double(__float_as_int(n), __float_as_int(p));
        }
        if (lane == 0) {
            float sum_pos_final = __int_as_float(__double2loint(packed));
            float sum_neg_final = __int_as_float(__double2hiint(packed));
            float dist_pos = sqrtf(sum_pos_final);
            float dist_neg = sqrtf(sum_neg_final);
            float loss = dist_pos - dist_neg + margin;
            loss = loss > 0.f ? loss : 0.f;
            // Fuse the final reduction directly here via atomicAdd, avoiding
            // a separate second-stage kernel launch and an extra global
            // memory write+read round trip of the per-row losses. Since
            // this kernel is memory-bandwidth bound (reading 3*dim floats
            // per block), the negligible atomic contention cost is far
            // outweighed by removing an entire kernel launch plus the
            // per-row_loss buffer traffic.
            atomicAdd(loss_sum, loss);
        }
    }
}
torch::Tensor cute_triplet_margin_loss(torch::Tensor anchor, torch::Tensor positive, torch::Tensor negative, double margin, double eps) {
    TORCH_CHECK(anchor.is_cuda() && positive.is_cuda() && negative.is_cuda(), "All inputs must be CUDA tensors");
    TORCH_CHECK(anchor.dim() == 2 && positive.dim() == 2 && negative.dim() == 2, "Inputs must be 2D");
    TORCH_CHECK(anchor.scalar_type() == at::kFloat, "Expect float32 tensors");
    TORCH_CHECK(anchor.sizes() == positive.sizes() && anchor.sizes() == negative.sizes(), "Shapes must match");
    auto A = anchor.contiguous();
    auto P = positive.contiguous();
    auto Nn = negative.contiguous();
    int batch = (int)A.size(0);
    int dim   = (int)A.size(1);
    auto out = torch::zeros({1}, A.options());
    int threads = 256; // smaller block size increases resident blocks per SM, improving latency hiding for this memory-bound reduction kernel
    dim3 block(threads);
    dim3 grid(batch);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    triplet_margin_loss_kernel<<<grid, block, 0, stream>>>(
        A.data_ptr<float>(), P.data_ptr<float>(), Nn.data_ptr<float>(),
        out.data_ptr<float>(), batch, dim, (float)margin, (float)eps);
    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE triplet margin loss launch failed");
    return (out / batch).squeeze();
}
"""

cute_ext = load_inline(
    name="cute_triplet_margin_loss_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_triplet_margin_loss"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/workspace/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    A model that computes Triplet Margin Loss using a custom fused CUTE/CUDA kernel.

    Parameters:
        margin (float): The margin between the positive and negative samples.
    """
    def __init__(self, margin=1.0):
        super(ModelNew, self).__init__()
        self.margin = float(margin)
        self.eps = 1e-6
        self._ext = cute_ext

    def forward(self, anchor, positive, negative):
        return self._ext.cute_triplet_margin_loss(anchor, positive, negative, self.margin, self.eps)

