    // Handle any tail elements when dim is not a multiple of 4.
    for (int i = dim4 * 4 + threadIdx.x; i < dim; i += blockDim.x) {
        float av = a_row[i];
        float pv = p_row[i];
        float nv = n_row[i];
        float dp = av - pv + eps;
        float dn = av - nv + eps;
        sum_pos += dp * dp;
        sum_neg += dn * dn;
    }

    // Warp-level reduction
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum_pos += __shfl_down_sync(0xffffffff, sum_pos, offset);
        sum_neg += __shfl_down_sync(0xffffffff, sum_neg, offset);
    }

    __shared__ float shared_pos[32];
    __shared__ float shared_neg[32];

    int lane = threadIdx.x & 31;
    int wid  = threadIdx.x >> 5;

    if (lane == 0) {
        shared_pos[wid] = sum_pos;
        shared_neg[wid] = sum_neg;
    }
    __syncthreads();

    int numWarps = (blockDim.x + 31) / 32;
    if (wid == 0) {
        sum_pos = (lane < numWarps) ? shared_pos[lane] : 0.f;
        sum_neg = (lane < numWarps) ? shared_neg[lane] : 0.f;
        for (int offset = 16; offset > 0; offset >>= 1) {
            sum_pos += __shfl_down_sync(0xffffffff, sum_pos, offset);
            sum_neg += __shfl_down_sync(0xffffffff, sum_neg, offset);
        }
        if (lane == 0) {
            float dist_pos = sqrtf(sum_pos);
            float dist_neg = sqrtf(sum_neg);
            float loss = dist_pos - dist_neg + margin;
            loss = loss > 0.f ? loss : 0.f;
            atomicAdd(out, loss);
        }
    }
}

torch::Tensor cute_triplet_margin_loss(torch::Tensor anchor, torch::Tensor positive, torch::Tensor negative, double margin, double eps) {
    TORCH_CHECK(anchor.is_cuda() && positive.is_cuda() && negative.is_cuda(), "All inputs must be CUDA tensors");
    TORCH_CHECK(anchor.dim() == 2 && positive.dim() == 2 && negative.dim() == 2, "Inputs must be 2D");
    TORCH_CHECK(anchor.scalar_type() == at::kFloat, "Expect float32 tensors");
    TORCH_CHECK(anchor.sizes() == positive.sizes() && anchor.sizes() == negative.sizes(), "Shapes must match");

    auto A = anchor.contiguous();
    auto P = positive.contiguous();
    auto Nn = negative.contiguous();

    int batch = (int)A.size(0);
    int dim   = (int)A.size(1);

    auto out = torch::zeros({1}, A.options());

    int threads = 256;
    dim3 block(threads);
    dim3 grid(batch);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    triplet_margin_loss_kernel<<<grid, block, 0, stream>>>(
        A.data_ptr<float>(), P.data_ptr<float>(), Nn.data_ptr<float>(),
        out.data_ptr<float>(), batch, dim, (float)margin, (float)eps);

    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE triplet margin loss launch failed");

    return (out / batch).squeeze();
}
